// The last whole weeks (weeks in Settings), Monday to Sunday, ending at the start of this Monday. Stripe takes Unix seconds.
// Which Monday it is comes from n8n's $now (Luxon) in the workflow's timezone (Workflow settings), so the
// Monday 09:00 run in Sydney or Auckland, which is still Sunday in UTC, picks the Monday that just started.
// The weeks themselves are cut at 00:00 UTC on those dates. East of UTC that is a few hours after the run,
// so the last hours of the final UTC Sunday are not in the chart.
const WEEKS = $('Settings').first().json.weeks;
if (!Number.isInteger(WEEKS) || WEEKS < 2 || WEEKS > 52) throw new Error('Set weeks in Settings to a whole number from 2 to 52.');
const WEEK = 7 * 86400;
const d = $now.startOf('day');
const m = d.minus({ days: d.weekday - 1 });
const monday = Date.UTC(m.year, m.month - 1, m.day) / 1000;
return [{ json: { from: monday - WEEKS * WEEK, to: monday, weeks: WEEKS } }];

// Approximation: the sum of amount_paid of paid invoices, by the week the invoice was created.
// No proration, refunds or churn, and tax is included. It is not MRR.
const { from, weeks } = $('Date range').first().json;
const { chartTitle } = $('Settings').first().json;
const WEEK = 7 * 86400;
const pages = $input.all().map((item) => item.json);
if (pages.some((page) => !Array.isArray(page.data))) throw new Error('Stripe did not return a list of invoices. Check the Stripe credential.');
if (pages.at(-1)?.has_more) throw new Error('More than 2000 paid invoices in ' + weeks + ' weeks: the figure would be wrong. Lower weeks in Settings.');
const invoices = pages.flatMap((page) => page.data).filter((inv) => inv.status === 'paid' && inv.created >= from && inv.created < from + weeks * WEEK);
if (invoices.length === 0) throw new Error('No paid invoices in the last ' + weeks + ' weeks, so there is nothing to chart.');

// One currency per chart: the one with the most money. Invoices in others are counted and left out.
const byCurrency = {};
for (const inv of invoices) {
  const rows = (byCurrency[inv.currency] ??= new Array(weeks).fill(0));
  rows[Math.floor((inv.created - from) / WEEK)] += inv.amount_paid;
}
const sum = (rows) => rows.reduce((a, b) => a + b, 0);
const currency = Object.keys(byCurrency).sort((a, b) => sum(byCurrency[b]) - sum(byCurrency[a]))[0];
const skipped = invoices.filter((inv) => inv.currency !== currency).length;

// Stripe amounts are in the currency's minor unit. ISK and UGX are zero-decimal but Stripe
// still sends them with two decimals.
const digits = ['isk', 'ugx'].includes(currency) ? 2 : new Intl.NumberFormat('en', { style: 'currency', currency }).resolvedOptions().maximumFractionDigits;
const values = byCurrency[currency].map((minor) => Math.round(minor / 10 ** digits));
const symbol = new Intl.NumberFormat('en', { style: 'currency', currency, currencyDisplay: 'narrowSymbol' }).formatToParts(0).find((p) => p.type === 'currency').value;
const prefix = symbol.length > 1 ? symbol + ' ' : symbol;

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const labels = values.map((_, i) => {
  const d = new Date((from + i * WEEK) * 1000);
  return MONTHS[d.getUTCMonth()] + ' ' + d.getUTCDate();
});

const last = values.at(-1);
const previous = values.at(-2);
const money = (n) => prefix + n.toLocaleString('en');
const change = previous > 0 ? Math.round(((last - previous) / previous) * 1000) / 10 : null;
const trend = change === null ? 'there was no revenue the week before' : change === 0 ? 'unchanged on the week before' : (change > 0 ? 'up ' : 'down ') + Math.abs(change) + '% on the week before';
const fallback = chartTitle + ': ' + money(last) + (change === null ? '' : ' (' + (change > 0 ? '+' : '') + change + '%)');
const alt = chartTitle + ' was ' + money(last) + ' in the week of ' + labels.at(-1) + ', ' + trend + '. Last ' + weeks + ' weeks of paid Stripe invoices.';

const chart = {
  type: 'line',
  data: { labels, datasets: [{ label: 'Revenue', data: values }] },
  options: { plugins: { title: { display: true, text: chartTitle }, subtitle: { display: true, text: 'Paid invoices, last ' + weeks + ' weeks' }, chartpng: { preset: 'kpi', previous, prefix, source: 'Stripe, paid invoices' } } },
};
const imageUrl = 'https://chartpng.dev/chart?c=' + encodeURIComponent(JSON.stringify(chart)) + '&w=800&h=400&dpr=2';
// Slack refuses an image block whose URL is longer than 3000 characters.
if (imageUrl.length > 3000) throw new Error('The chart URL is longer than 3000 characters.');

const note = 'Approximate: the sum of paid Stripe invoices by week (UTC, Monday to Sunday), tax included. No proration, refunds or churn.' + (skipped ? ' ' + skipped + ' invoice(s) in other currencies left out.' : '');
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: chartTitle } },
  { type: 'image', image_url: imageUrl, alt_text: alt },
  { type: 'context', elements: [{ type: 'mrkdwn', text: note }] },
];
return [{ json: { imageUrl, fallback, alt, blocks } }];
